import{_ as t,a,c as o,ac as s}from"./chunks/framework.BSuaGltH.js";const p=JSON.parse(`{"title":"第一册：英语初阶 · Lesson 30 What must I do?","description":"学习 祈使句与 must，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第一册：英语初阶 · Lesson 30 What must I do?","description":"学习 祈使句与 must，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第1册课时","summary":"学习 祈使句与 must，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第一册：英语初阶 · Lesson 29 Come in, Amy.","link":"/life/english/new-concept/book-1/unit-02/lesson-029"},"next":{"text":"第一册：英语初阶 · Lesson 31 Where's Sally?","link":"/life/english/new-concept/book-1/unit-02/lesson-031"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第一册：英语初阶 · Lesson 29 Come in, Amy.","link":"/life/english/new-concept/book-1/unit-02/lesson-029"},"next":{"text":"第一册：英语初阶 · Lesson 31 Where's Sally?","link":"/life/english/new-concept/book-1/unit-02/lesson-031"}},"headers":[],"relativePath":"life/english/new-concept/book-1/unit-02/lesson-030.md","filePath":"life/english/new-concept/book-1/unit-02/lesson-030.md"}`),n={name:"life/english/new-concept/book-1/unit-02/lesson-030.md"};function i(l,e,r,d,h,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="第一册-英语初阶-·-lesson-30-what-must-i-do" tabindex="-1">第一册：英语初阶 · Lesson 30 What must I do? <a class="header-anchor" href="#第一册-英语初阶-·-lesson-30-what-must-i-do" aria-label="Permalink to &quot;第一册：英语初阶 · Lesson 30 What must I do?&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-1/contents">本册目录</a> · <a href="/life/english/new-concept/book-1/unit-02/overview">单元 2</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-029">配套课 Lesson 29</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>理解整理房间的指令 本课要掌握祈使句与 must，能够理解人物、对象及说话目的，并把相同结构用于自己的生活。本课将前一课的结构迁移到另一个例子；请先口头作答，再写出完整句子，不只替换单个单词。</p><p>本课为配套句型训练；先回顾相邻奇数课，再独立完成本页的原创练习。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>tidy</td><td>/ˈtaɪdi/</td><td>v.</td><td>整理</td><td>tidy the room</td></tr><tr><td>dust</td><td>/dʌst/</td><td>v.</td><td>除尘</td><td>dust the shelf</td></tr><tr><td>sweep</td><td>/swiːp/</td><td>v.</td><td>扫</td><td>sweep the floor</td></tr><tr><td>open</td><td>/ˈəʊpən/</td><td>v.</td><td>打开</td><td>open the window</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>please sit down — 礼貌指令</li><li>must finish — 表示必须完成</li></ul><h2 id="语法讲解-祈使句与-must" tabindex="-1">语法讲解：祈使句与 must <a class="header-anchor" href="#语法讲解-祈使句与-must" aria-label="Permalink to &quot;语法讲解：祈使句与 must&quot;">​</a></h2><p>肯定祈使句通常以动词原形开头，省略主语 you；please 可放句首或句末，句末通常用逗号隔开。must 表示必要或要求，后接动词原形，不加 to。询问要做什么用 What must I do?，将 must 放在主语前。不要把命令与正在发生的动作混淆，Open ... 是要求，不是陈述。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>I must tidy my desk before lunch.</p></blockquote><p>午饭前我必须整理书桌。</p><p>I 是主语，must 后直接接 tidy；my desk 是宾语，before lunch 说明完成动作的时间界限。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>must 后不用 to；must to tidy 应改为 must tidy。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>请同伴朗读本课原创示范，或先自行录音，再遮住文字听写“I must tidy my desk before lunch.”。核对词序与漏词后，用下方句子分析说明每个词组的作用。随后不看原句说出中文意思，再换一个对象重新说一句。没有录音时，可用同伴朗读和问答完成同样的训练。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>I must tidy my desk before lunch. Please close the cupboard quietly.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>围绕“理解整理房间的指令”写两至三句，再读给同伴听。至少使用一次祈使句与 must，改变一个人物或对象后再说一遍。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>I 是主语，must 后直接接 tidy；my desk 是宾语，before lunch 说明完成动作的时间界限。 Please close 是礼貌指令，the cupboard 是 close 的宾语；quietly 是副词，修饰关柜子的动作。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>删去错误词：I must to tidy my desk.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> I must tidy my desk.</p><p><strong>解析：</strong> 按本课规则判断：肯定祈使句通常以动词原形开头，省略主语 you；please 可放句首或句末，句末通常用逗号隔开。must 表示必要或要求，后接动词原形，不加 to。询问要做什么用 What must I do?，将 must 放在主语前。不要把命令与正在发生的动作混淆，Open ... 是要求，不是陈述。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>把“午饭前我必须整理书桌。”译成英语，保留人物、动作与时间信息。</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> I must tidy my desk before lunch.</p><p><strong>解析：</strong> I 是主语，must 后直接接 tidy；my desk 是宾语，before lunch 说明完成动作的时间界限。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>说明下面句子表达的信息，并译成中文：Please close the cupboard quietly.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 请轻轻关上橱柜。</p><p><strong>解析：</strong> Please close 是礼貌指令，the cupboard 是 close 的宾语；quietly 是副词，修饰关柜子的动作。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：祈使句与 must。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-1/unit-02/grammar">单元语法</a> · <a href="/life/english/new-concept/book-1/unit-02/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-1/unit-02/review">单元自测</a></p><p><a href="/life/english/new-concept/book-1/unit-02/lesson-029">上一课</a> · <a href="/life/english/new-concept/book-1/unit-02/overview">单元目录</a> · <a href="/life/english/new-concept/book-1/unit-02/lesson-031">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const m=t(n,[["render",i]]);export{p as __pageData,m as default};
